var passages = window.SugarCube.Story.passages || {};
var locs = Object.keys(passages).filter(function(k){ return k.startsWith('Location_'); });
return JSON.stringify(locs);

var V = window.SugarCube.State.variables;
// Set up Frank arc state for max eligibility
V.player.core_traits.npc_frank_stage = 2;
V.player.core_traits.corruption = 100;
// Find Frank's UUID via npcs map
var npcs = V.npcs || {};
for (var uuid in npcs) {
  if (npcs[uuid].name === 'Frank') {
    npcs[uuid].core_traits.trust = 10;
    npcs[uuid].core_traits.arousal = 30;
    npcs[uuid].core_traits.corruption = 15;
  }
}
// Reset random cooldowns to ensure fresh rolls
V.game_state.random_cooldowns = {};
return JSON.stringify({frank_stage: V.player.core_traits.npc_frank_stage, time: V.game_state.time_state});

var V = window.SugarCube.State.variables;
V.game_state.time_state.current_hour = 22;
V.game_state.time_state.current_minute = 30;
V.game_state.random_cooldowns = {};
window.SugarCube.Engine.play("Location_Kitchen");
return 'Navigated to Kitchen at 22:30';

// Reset state, set time to 06:00, retry kitchen 10 times to count random fires
var V = window.SugarCube.State.variables;
V.game_state.time_state.current_hour = 6;
V.game_state.time_state.current_minute = 0;
V.flags.frank_late_night_used = false;  // reset flag from previous test
var results = [];
for (var i = 0; i < 10; i++) {
  V.game_state.random_cooldowns = {};  // reset cooldown each attempt
  V.flags.frank_coffee_alone_today = false;  // reset daily flag if exists
  // Manually invoke the substitution check (mimicking Location_Kitchen entry)
  var redirect = setup.getStoryCanvasRedirect ? setup.getStoryCanvasRedirect('a06ad6e4-7395-4ddc-a608-3e36cdfd7e07') : null;
  // Try with the real loc UUID — let me find it
  var locId = null;
  for (var luid in (setup.help_data || {}).locationCanvases || {}) {
    var canvases = setup.help_data.locationCanvases[luid] || [];
    for (var c of canvases) { if (c.id === 'scene_kitchen_frank_coffee_alone') { locId = luid; break; } }
    if (locId) break;
  }
  redirect = setup.getStoryCanvasRedirect(locId);
  results.push({attempt: i+1, redirect: redirect, locId: locId});
}
return JSON.stringify(results);

var hd = setup.help_data || {};
var lc = hd.locationCanvases || {};
var locUuids = Object.keys(lc);
var summary = {};
for (var u of locUuids) {
  var list = lc[u] || [];
  summary[u] = list.map(function(c){ return c.id + ' [' + (c.triggerMode || 'manual') + ']'; });
}
return JSON.stringify(summary, null, 2);

var hd = setup.help_data || {};
var lc = hd.locationCanvases || {};
return JSON.stringify({ keyCount: Object.keys(lc).length, sample: Object.keys(lc).slice(0,3) });

var setup = window.SugarCube.setup;
var V = window.SugarCube.State.variables;
V.game_state.time_state.current_hour = 6;
V.game_state.time_state.current_minute = 0;
V.flags.frank_late_night_used = false;
// Find loc_kitchen UUID via help_data
var hd = setup.help_data || {};
var lc = hd.locationCanvases || {};
var kitchenUuid = null;
for (var u of Object.keys(lc)) {
  for (var c of lc[u]) {
    if (c.id === 'scene_kitchen_frank_coffee_alone') { kitchenUuid = u; break; }
  }
  if (kitchenUuid) break;
}
if (!kitchenUuid) return 'kitchen not found in locationCanvases';
// Roll random encounters 20 times, count fires
var fires = 0;
var details = [];
for (var i = 0; i < 20; i++) {
  V.game_state.random_cooldowns = {};
  V.flags.frank_coffee_alone_today = false;
  V.flags.frank_late_night_used = false;
  var r = setup.checkRandomEncounters(kitchenUuid);
  if (r) { fires++; details.push(r); }
}
return JSON.stringify({kitchenUuid: kitchenUuid, fires: fires, of: 20, sample: details.slice(0, 5)});

var setup = window.SugarCube.setup;
var hd = setup.help_data || {};
var lc = hd.locationCanvases || {};
var allCanvasIds = [];
for (var u of Object.keys(lc)) {
  for (var c of lc[u]) {
    allCanvasIds.push({loc: u, id: c.id, mode: c.triggerMode});
  }
}
return JSON.stringify({total: allCanvasIds.length, frankRandoms: allCanvasIds.filter(c => c.mode === 'random' && c.id.indexOf('frank') >= 0)});

var setup = window.SugarCube.setup;
var hd = setup.help_data || {};
var lc = hd.locationCanvases || {};
// Look for any of the 11 flipped canvas IDs in any form
var search = ['scene_kitchen_frank_coffee_alone','scene_hallway_frank_pass','scene_kitchen_late_night_raid','scene_porch_frank_evening_smoke'];
var found = {};
for (var u of Object.keys(lc)) {
  for (var c of lc[u]) {
    for (var s of search) {
      if (c.id === s || (c.id || '').indexOf(s) >= 0 || (c.name || '').indexOf(s) >= 0) {
        found[s] = {loc: u, id: c.id, name: c.name, mode: c.triggerMode, chance: c.chance};
      }
    }
  }
}
// Also check help_data for other indices
var allKeys = Object.keys(hd);
return JSON.stringify({found: found, helpDataKeys: allKeys});

var setup = window.SugarCube.setup;
var hd = setup.help_data || {};
var lc = hd.locationCanvases || {};
var all = [];
for (var u of Object.keys(lc)) {
  for (var c of lc[u]) {
    if ((c.name || '').toLowerCase().indexOf('kitchen') >= 0 || (c.name || '').toLowerCase().indexOf('hallway') >= 0) {
      all.push({loc: u.slice(0,8), id: c.id, name: c.name, mode: c.triggerMode, chance: c.chance});
    }
  }
}
return JSON.stringify(all, null, 2);

var setup = window.SugarCube.setup;
var V = window.SugarCube.State.variables;
var KITCHEN_LOC = '44304546';  // partial — find full
var hd = setup.help_data || {};
var lc = hd.locationCanvases || {};
var fullKitchen = Object.keys(lc).find(function(k){ return k.startsWith(KITCHEN_LOC); });
var HALLWAY_LOC = '32c1b960';
var fullHallway = Object.keys(lc).find(function(k){ return k.startsWith(HALLWAY_LOC); });

// Roll kitchen at 06:00 (coffee_alone window) — 30 attempts
V.game_state.time_state.current_hour = 6;
V.game_state.time_state.current_minute = 0;
var fires = {};
for (var i = 0; i < 30; i++) {
  V.game_state.random_cooldowns = {};
  // Reset all daily flags to allow re-fire
  if (V.flags) {
    V.flags.frank_late_night_used = false;
    V.flags.frank_coffee_alone_today = false;
    V.flags.frank_kitchen_afternoon_today = false;
  }
  var r = setup.checkRandomEncounters(fullKitchen);
  if (r) { fires[r] = (fires[r]||0) + 1; }
}

// Same at hallway 21:30 (frank_pass + late_drink window)
V.game_state.time_state.current_hour = 21;
V.game_state.time_state.current_minute = 30;
var hallwayFires = {};
for (var i = 0; i < 30; i++) {
  V.game_state.random_cooldowns = {};
  if (V.flags) {
    V.flags.frank_hallway_pass_today = false;
    V.flags.frank_hallway_late_drink_today = false;
  }
  var r = setup.checkRandomEncounters(fullHallway);
  if (r) { hallwayFires[r] = (hallwayFires[r]||0) + 1; }
}

return JSON.stringify({
  kitchen_at_0600: { fires: Object.values(fires).reduce(function(a,b){return a+b;},0), of: 30, breakdown: fires },
  hallway_at_2130: { fires: Object.values(hallwayFires).reduce(function(a,b){return a+b;},0), of: 30, breakdown: hallwayFires }
});

var setup = window.SugarCube.setup;
var V = window.SugarCube.State.variables;
