var setup = window.SugarCube.setup;
var V = window.SugarCube.State.variables;
var hd = setup.help_data || {};
var lc = hd.locationCanvases || {};
// Find office UUID
var officeUuid = null;
for (var u of Object.keys(lc)) {
  for (var c of lc[u]) {
    if (c.id && (c.name || '').indexOf("Frank's office — Diana on the phone") >= 0) { officeUuid = u; break; }
  }
  if (officeUuid) break;
}

V.game_state.time_state.current_hour = 19;
V.game_state.time_state.current_minute = 30;
var fires = 0;
for (var i = 0; i < 30; i++) {
  V.game_state.random_cooldowns = {};
  if (V.flags) V.flags.frank_diana_phone_today = false;
  var r = setup.checkRandomEncounters(officeUuid);
  if (r) fires++;
}
return JSON.stringify({office_19_30: { fires: fires, of: 30 }, officeUuid: officeUuid});

var setup = window.SugarCube.setup;
var V = window.SugarCube.State.variables;
// Find the diana_call canvas in locationCanvases
var hd = setup.help_data || {};
var lc = hd.locationCanvases || {};
var dianaC = null;
for (var u of Object.keys(lc)) {
  for (var c of lc[u]) {
    if ((c.name || '').indexOf('Diana on the phone') >= 0) { dianaC = c; break; }
  }
  if (dianaC) break;
}
if (!dianaC) return 'not found';

// Check each condition + schedule
var validityResult = {
  isCanvasValid: setup.isCanvasValid(dianaC),
  scheduleActive: dianaC.scheduleParams ? setup.isScheduleActive(dianaC.scheduleParams) : 'no schedule',
  conditionsMet: dianaC.conditions ? setup.triggerConditionsSatisfied(dianaC.conditions) : 'no conditions',
  conditions: dianaC.conditions,
  schedules: dianaC.scheduleParams,
  flagState: {
    frank_restrict_declared: V.flags && V.flags.frank_restrict_declared,
    frank_diana_phone_today: V.flags && V.flags.frank_diana_phone_today,
    arrived_at_franks: V.flags && V.flags.arrived_at_franks,
  },
  npcStage: V.player && V.player.core_traits ? V.player.core_traits.npc_frank_stage : '?',
};
return JSON.stringify(validityResult, null, 2);
